import {
	mapState
} from "vuex";
import {
	cascaderListApi,
	changeListApi,
	allLabelApi
} from "@/api/product";
export default {
	name: "index",
	props: {
		goodsType: {
			type: Number,
			default: 0,
		},
		is_new: {
			type: String,
			default: "",
		},
		diy: {
			type: Boolean,
			default: false,
		},
		isdiy: {
			type: Boolean,
			default: false,
		},
		ischeckbox: {
			type: Boolean,
			default: false,
		},
		datas: {
			type: Object,
			default: function() {
				return {};
			},
		},
	},
	data() {
		return {
			labelSelect: [],
			cateIds: [],
			treeSelect: [],
			formValidate: {
				page: 1,
				limit: 10,
				cate_id: "",
				store_name: "",
				is_new: this.is_new,
				store_label_id: ""
			},
			total: 0,
			loading: false,
			grid: {
				xl: 10,
				lg: 10,
				md: 12,
				sm: 24,
				xs: 24,
			},
			tableList: [],
			currentid: 0,
			productRow: {},
			images: []
		};
	},
	computed: {
		...mapState("admin/layout", ["isMobile"]),
		labelWidth() {
			return this.isMobile ? undefined : 120;
		},
		labelPosition() {
			return this.isMobile ? "top" : "right";
		},
	},
	created() {},
	mounted() {
		this.goodsCategory();
		this.getList();
		this.getAllLabelApi();
	},
	methods: {
		getAllLabelApi() {
			allLabelApi().then(res => {
				this.labelSelect = res.data
			}).catch(err => {
				this.$Message.error(err.msg);
			})
		},
		// 商品分类；
		goodsCategory() {
			cascaderListApi(1)
				.then((res) => {
					this.treeSelect = res.data;
				})
				.catch((res) => {
					this.$Message.error(res.msg);
				});
		},
		pageChange({ currentPage, pageSize }) {
			this.formValidate.page = currentPage;
			this.formValidate.limit = pageSize;
			this.getList();
		},
		// 列表
		getList() {
			this.loading = true;
			if (this.goodsType) {
				this.formValidate.is_presale_product = 0;
				this.formValidate.is_vip_product = 0;
			}
			this.formValidate.cate_id = this.cateIds[this.cateIds.length - 1]
			changeListApi(this.formValidate)
				.then(async (res) => {
					let list = res.data.list;
					list.forEach(item=>{
						item.attrValue.forEach(j=>{
							j.store_name = j.suk,
							j.cate_name = item.cate_name,
							j.store_label = item.store_label
						})
					})
					this.tableList = list;
					this.total = res.data.count;
					this.loading = false;
				})
				.catch((res) => {
					this.loading = false;
					this.$Message.error(res.msg);
				});
		},
		ok() {
			 let selectRecords = this.$refs.xTree.getCheckboxRecords()
			let goodsattr = [];
			selectRecords.forEach(function(item) {
				if(item.hasOwnProperty('product_id')){
					goodsattr.push(item)
				}
			});
			if (goodsattr.length > 0) {
				this.$emit("getProductId", goodsattr);
			} else {
				this.$Message.warning("请先选择商品");
			}
		},
		treeSearchs(value) {
			this.cateIds = value;
			this.formValidate.page = 1;
			this.getList();
		},
		// 表格搜索
		userSearchs() {
			this.formValidate.page = 1;
			this.getList();
		},
		clear() {
			this.productRow.id = "";
			this.currentid = "";
		},
	},
};
